mapper.select:
/*selectMasterMpRqBuyerDesignAgentList*/
SELECT BUYER, AGENT, AGENT_CHOICE_SEQ, REQ_DEPT_NAME, REQ_USER_NAME, REQ_USER_TEL, ADD_DATE, DEL_DATE, STATUS FROM BUYER_AGENT_CHOICE WHERE 1=1 AND BUYER = #{st_buyer} AND AGENT = #{st_agent}
AND STATUS != 'D'
ORDER BY BUYER, AGENT, STATUS, AGENT_CHOICE_SEQ

mapper.update:
/*updateMasterMpRqBuyerDesignAgent*/

		UPDATE	BUYER_AGENT_CHOICE
		SET		STATUS = 'R',
				REQ_DEPT_NAME = #{REQ_DEPT_NAME},
				REQ_USER_NAME = #{REQ_USER_NAME},
				REQ_USER_TEL = #{REQ_USER_TEL}
		WHERE	1=1
		AND		BUYER = #{st_buyer}
		AND		AGENT = #{st_agent}
		AND		AGENT_CHOICE_SEQ = #{AGENT_CHOICE_SEQ}

/*deleteMasterMpRqBuyerDesignAgent*/

		UPDATE	BUYER_AGENT_CHOICE
		SET		STATUS = 'D',
				DEL_USER_ID = #{USER_ID},
				DEL_DATE = SYSDATE
		WHERE	1=1
		AND		BUYER = #{st_buyer}
		AND		AGENT = #{st_agent}
		AND		AGENT_CHOICE_SEQ = #{AGENT_CHOICE_SEQ}
